/*
# Expand Exercise Catalog — Part 1: Pro Tier

Adds ~50 pro-tier exercises. Uses ON CONFLICT to skip existing names.
*/

ON CONFLICT (name) DO NOTHING;

SELECT COUNT(*) as total, COUNT(*) FILTER (WHERE access_tier = 'free') as free, COUNT(*) FILTER (WHERE access_tier = 'pro') as pro, COUNT(*) FILTER (WHERE access_tier = 'plus') as plus FROM exercises;
